def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[2:] + filtered_rows[:2]

    group_map = {}
    for group, score, timestamp, name in rotated_rows:
        if group not in group_map:
            group_map[group] = []
        group_map[group].append((score, timestamp, name))

    result = []
    for group in sorted(group_map.keys()):
        entries = group_map[group]
        best_entry = None
        for score, timestamp, name in entries:
            if best_entry is None:
                best_entry = (score, timestamp, name)
            else:
                best_score, best_timestamp, best_name = best_entry
                if score > best_score:
                    best_entry = (score, timestamp, name)
                elif score == best_score and timestamp < best_timestamp:
                    best_entry = (score, timestamp, name)
                elif score == best_score and timestamp == best_timestamp and name > best_name:
                    best_entry = (score, timestamp, name)

        if best_entry:
            result.append([group, best_entry[2]])

    return result

